// Verifies the generated preview (dist-preview) against the fixed sources:
// the worker bundle and worker-source regenerate byte-identically, and the
// preview tree is exactly public/ plus the two generated files.

import { createHash } from 'node:crypto';
import { readFile, readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const publicDir = path.join(root, 'public');
const distDir = path.join(root, 'dist-preview');
let failures = 0;

function check(ok, label) {
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label}`);
  if (!ok) failures += 1;
}

async function listFiles(dir, base = dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...(await listFiles(full, base)));
    else if (entry.isFile()) files.push(path.relative(base, full));
  }
  return files.sort();
}

const sha = (text) => createHash('sha256').update(text, 'utf8').digest('hex');

const core = await readFile(path.join(publicDir, 'js', 'core', 'audit.mjs'), 'utf8');
const entry = await readFile(path.join(publicDir, 'js', 'worker-entry.mjs'), 'utf8');
const expectedBundle =
  '// Generated by scripts/build.mjs from fixed source bytes.\n' +
  '// Do not edit: re-run `npm run build:preview`.\n' +
  core +
  '\n' +
  entry;

let actualBundle = null;
let actualSource = null;
try {
  actualBundle = await readFile(path.join(distDir, 'js', 'worker-bundle.mjs'), 'utf8');
  actualSource = await readFile(path.join(distDir, 'js', 'worker-source.mjs'), 'utf8');
} catch {
  check(false, 'dist-preview: generated worker files exist (run npm run build:preview first)');
}
if (actualBundle !== null) {
  check(actualBundle === expectedBundle, 'dist-preview/js/worker-bundle.mjs: regenerates byte-identically');
  const expectedSource =
    '// Generated by scripts/build.mjs from fixed source bytes.\n' +
    '// Do not edit: re-run `npm run build:preview`.\n' +
    `export const WORKER_SOURCE = ${JSON.stringify(expectedBundle)};\n`;
  check(actualSource === expectedSource, 'dist-preview/js/worker-source.mjs: regenerates byte-identically');
  check(actualBundle.includes('self.onmessage'), 'worker bundle: contains the message handler');
  check(!/^\s*import\b/m.test(actualBundle), 'worker bundle: no imports');
}

const publicFiles = await listFiles(publicDir);
const distFiles = await listFiles(distDir);
const generated = ['js/worker-bundle.mjs', 'js/worker-source.mjs'];
const expectedDist = [...publicFiles, ...generated].sort();
check(
  JSON.stringify(distFiles) === JSON.stringify(expectedDist),
  'dist-preview: file list is public/ + two generated files',
);
for (const rel of publicFiles) {
  const a = await readFile(path.join(publicDir, rel));
  const b = await readFile(path.join(distDir, rel));
  if (!a.equals(b)) {
    check(false, `dist-preview/${rel}: byte-identical to public/`);
  }
}
console.log(`checked ${publicFiles.length} public files copied byte-identically`);

if (failures > 0) {
  console.error(`check-generated.mjs: ${failures} failure(s)`);
  process.exit(1);
}
console.log('check-generated.mjs: generated preview verified');
console.log(`worker bundle sha256: ${sha(expectedBundle)}`);
